import java.util.List;
import java.util.ArrayList;

record Student(int roll) implements Comparable<Student> {
    @Override
    public int compareTo(Student other) { return Integer.compare(roll, other.roll); }
}

class Main {
    public static void main(String[] args) throws Exception {
        List<Student> students = new ArrayList<>(List.of(new Student(7), new Student(2)));
        students.sort(null);
        for (Student student : students) { System.out.println(student.roll()); }
    }
}

import java.util.List;
import java.util.ArrayList;
import java.util.Comparator;

record Result(int roll, int mark) { }

class Main {
    public static void main(String[] args) throws Exception {
        List<Result> results = new ArrayList<>(List.of(
            new Result(4, 80), new Result(2, 80), new Result(1, 90)));
        Comparator<Result> ranking = Comparator.comparingInt(Result::mark).reversed()
            .thenComparingInt(Result::roll);
        results.sort(ranking);
        for (Result result : results) { System.out.println(result.roll() + " " + result.mark()); }
    }
}

